update public.institutions set
  feedback_summary_student = 'Смешанные отзывы: доброжелательные сотрудники, для тех, кто хочет учиться — знания реально дают. Заметная и повторяющаяся критика — короткие пары «для галочки», ощущение коммерциализации образовательного процесса, единичные упоминания коррупции.',
  feedback_positive_highlights = '{"компетентный преподавательский состав для мотивированных студентов","доброжелательные сотрудники"}',
  feedback_negative_highlights = '{"формальный подход части преподавателей","ощущение чрезмерной коммерциализации"}',
