update public.institutions set
  feedback_summary_student = 'Отзывы неоднородны и заметно изменились после смены руководства в 2018 году (сокращение половины профессорского состава). Плюсы: активная общественная жизнь, престижные преподаватели. Серьёзная критика — плохая организация учебного процесса, неудобное расположение (30-40 минут от метро), отдельные жалобы на моральное давление на студентов.',
  feedback_positive_highlights = '{"активная общественная жизнь","престижные преподаватели-практики"}',
  feedback_negative_highlights = '{"плохая организация учебного процесса","неудобная транспортная доступность","жалобы на моральное давление после смены руководства"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Северо-Западный государственный медицинский университет имени И.И. Мечникова' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы неоднородны и сильно зависят от программы и года поступления (программа заметно меняется). Плюсы: отзывчивые преподаватели, насыщенная внеучебная жизнь, хорошая столовая и библиотека, демократичная цена обучения. Критика — посредственное качество образования по мнению части студентов, проблемы с расписанием, недостаточное внимание к иностранным студентам.',
  feedback_positive_highlights = '{"насыщенная внеучебная жизнь","демократичная стоимость обучения","отзывчивые преподаватели"}',
  feedback_negative_highlights = '{"нестабильность программы год от года","проблемы с расписанием"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'РАНХиГС Санкт-Петербург' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Ведущий IT-вуз страны с огромным конкурсом и репутацией. Отзывы сильно полярны: часть студентов подтверждает практическую пользу полученных знаний, но заметная критика — устаревшая программа по ряду направлений, резкая критика отношения деканата («скотское», «всё в штыки»), проблемы с общежитиями (иногда в часе езды от вуза).',
  feedback_positive_highlights = '{"ведущая репутация в сфере IT","практическая польза знаний по ряду направлений"}',
  feedback_negative_highlights = '{"устаревшая программа по части направлений","резкая критика отношения деканата к студентам","удалённые общежития"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Национальный исследовательский университет ИТМО' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы в основном положительные: подробные объяснения материала, вежливые сотрудники, индивидуальный подход, бесплатный автобус от метро, возможность помесячной оплаты. Критика — практика носит скорее теоретический характер, не всегда приводит к обещанному трудоустройству, деканат медленно отвечает на вопросы.',
  feedback_positive_highlights = '{"индивидуальный подход к обучению","гибкая помесячная оплата","удобная логистика (бесплатный автобус от метро)"}',
  feedback_negative_highlights = '{"практика зачастую формальна, без реального трудоустройства","медленная работа деканата"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Университет при Межпарламентской Ассамблее ЕврАзЭС' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Одна из лучших бизнес-школ России, СНГ и Восточной Европы по мнению студентов (25 положительных отзывов на одной из площадок, 0 отрицательных). Сильные карьерные связи, обучение на английском, хакатоны и встречи с практиками. Из минусов — очень высокая учебная нагрузка (особенно совмещая с работой) и дорогое проживание.',
  feedback_positive_highlights = '{"одна из лучших бизнес-школ региона","сильный карьерный центр и связи с международными компаниями","насыщенная жизнь: хакатоны, кейс-чемпионаты"}',
  feedback_negative_highlights = '{"очень высокая учебная нагрузка","дорогое и не всегда удобное жильё"}',
