update public.institutions set
  feedback_summary_student = 'Единственный в мире вуз, готовящий мастеров по 20+ видам традиционных художественных промыслов — уникальная образовательная ниша. Отзывы сильно полярны: часть студентов хвалит компетентность педагогов и индивидуальный подход, другая часть жалуется на жёсткую, местами репрессивную дисциплину и предвзятое отношение части преподавателей.',
  feedback_positive_highlights = '{"уникальные программы традиционных художественных промыслов","индивидуальный подход к части студентов"}',
  feedback_negative_highlights = '{"жёсткая, местами репрессивная дисциплина","предвзятое отношение части преподавателей"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Российский университет традиционных художественных промыслов' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы курсантов сильно полярны, характерны для силового вуза. Плюсы: воспитание дисциплины и ответственности, дружба между курсантами разных регионов, поддержка курсовых офицеров. Серьёзная критика — плохое питание (много расходов за свой счёт), нехватка мест в казарме после 1 курса, состояние санузлов, жёсткая и не всегда справедливая система увольнительных.',
  feedback_positive_highlights = '{"воспитание дисциплины и ответственности","дружба между курсантами из разных регионов"}',
  feedback_negative_highlights = '{"плохое питание, дополнительные расходы за свой счёт","нехватка мест в казарме после 1 курса","жёсткая система увольнительных"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Санкт-Петербургский университет Федеральной службы исполнения наказаний' and city = 'Санкт-Петербург';
